/**
 * Parse a Vollna job-alert email into raw job records.
 *
 * Pure: no I/O, no globals, no dependencies. This module is unit tested by
 * vitest AND inlined verbatim into the n8n "parse" Code node by
 * scripts/build-workflow.mjs, so it must stay dependency free.
 *
 * A Vollna alert can carry several jobs in one email. Segmentation is driven by
 * Upwork job URLs: every job in the digest links to one, and the ~token in that
 * URL is the only identifier Upwork guarantees to be stable, which makes it the
 * right dedupe key.
 *
 * Field extraction is deliberately pattern-table driven. Vollna's template will
 * change eventually; when it does, the fix belongs in FIELD_PATTERNS and a new
 * fixture under tests/fixtures/, not in the control flow below.
 */

// The ~token is the stable Upwork job id. Vollna wraps job links in tracking
// redirects often enough that we look for the token anywhere in the URL.
const JOB_URL_RE =
  /https?:\/\/(?:[\w.-]*\.)?upwork\.com\/[^\s"'<>)\]]*?~([0-9a-zA-Z]{12,})/g;

const FIELD_PATTERNS = {
  fixedBudget: /(?:budget|fixed[\s-]*price)\D{0,16}\$\s*([\d,]+(?:\.\d{1,2})?)/i,
  hourlyRange:
    /\$\s*([\d,.]+)\s*(?:-|–|—|to)\s*\$\s*([\d,.]+)\s*(?:\/|\s)?\s*(?:hr|hour)/i,
  hourlySingle: /\$\s*([\d,.]+)\s*(?:\/|\s)?\s*(?:hr|hour)\b/i,
  clientSpend: /\$\s*([\d,.]+)\s*([KkMm])?\+?\s*(?:total\s+)?spent/i,
  clientHires: /(\d+)\s+hires?\b/i,
  clientRating: /\b([0-5](?:\.\d{1,2})?)\s*(?:\/\s*5|stars?\b|\brating)/i,
  clientJobsPosted: /(\d+)\s+jobs?\s+posted/i,
  paymentVerified: /payment\s*(?:method\s*)?verified/i,
  proposals: /(\d+)\s+proposals?\b/i,
  country: /(?:country|location)\s*[:\-]\s*([A-Za-z][A-Za-z .'-]{1,40})/i,
  postedAt: /posted\s*(?:on)?\s*[:\-]?\s*([A-Za-z0-9,:\s/+-]{4,40}?)(?:\r?\n|$)/i,
  experienceLevel: /\b(entry[\s-]*level|intermediate|expert)\b/i,
};

// Lines that are chrome, not content: Vollna footer, unsubscribe, filter names.
const CHROME_RE =
  /^(?:unsubscribe|manage (?:your )?(?:alerts|filters)|vollna|view (?:this )?job|apply now|powered by|you (?:are )?receiv|this email|sent to|filter:|\W*$)/i;

/** Decode the handful of HTML entities that actually show up in these emails. */
function decodeEntities(s) {
  const named = {
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
    ndash: '-', mdash: '-', rsquo: "'", lsquo: "'", ldquo: '"', rdquo: '"',
    hellip: '...', middot: '.', bull: '*',
  };
  return String(s)
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => (n.toLowerCase() in named ? named[n.toLowerCase()] : m));
}

/**
 * Flatten an HTML email body to text, rendering anchors as `label <href>` so a
 * job's title and its URL survive on the same line. That adjacency is what the
 * title extraction below relies on.
 *
 * The href is parked behind control-character sentinels while the remaining
 * tags are stripped, because an already-rewritten `<https://...>` is itself
 * tag-shaped and would otherwise be deleted by the strip pass.
 */
function htmlToText(html) {
  if (!html) return '';
  return decodeEntities(
    String(html)
      .replace(/<!--[\s\S]*?-->/g, '')
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
      .replace(/<a\b[^>]*\bhref\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,
        (_, href, label) => ` ${label.replace(/<[^>]*>/g, ' ')} \u0001${href}\u0002 `)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|tr|li|h[1-6]|table|td)>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\u0001/g, '<')
      .replace(/\u0002/g, '>')
  )
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function toNumber(raw, suffix) {
  if (raw == null) return null;
  const n = Number(String(raw).replace(/,/g, ''));
  if (!Number.isFinite(n)) return null;
  const mult = suffix ? { k: 1e3, m: 1e6 }[String(suffix).toLowerCase()] || 1 : 1;
  return n * mult;
}

function match(segment, key) {
  const m = segment.match(FIELD_PATTERNS[key]);
  return m || null;
}

/**
 * Pick the job description out of a segment: the longest run of prose that is
 * not a label line, not chrome, and not the title itself.
 */
function extractDescription(segment, title) {
  const candidates = segment
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l.length > 60)
    .filter((l) => !CHROME_RE.test(l))
    .filter((l) => l !== title)
    .filter((l) => !/^\w[\w ]{0,20}:\s*\S/.test(l) || l.length > 140);
  if (!candidates.length) return '';
  return candidates.sort((a, b) => b.length - a.length)[0];
}

/**
 * Title = the text preceding the job URL on its own line. Falls back to the
 * previous non-chrome line, which is where Vollna puts it when the link markup
 * wraps.
 */
function extractTitle(segment, url) {
  const lines = segment.split('\n');
  const idx = lines.findIndex((l) => l.includes(url));
  if (idx === -1) return '';
  const inline = lines[idx].split(`<${url}>`)[0].replace(url, '').trim();
  const clean = (s) => s.replace(/[\s|>·•\-]+$/, '').replace(/^[\s|<·•\-]+/, '').trim();
  if (clean(inline).length >= 8) return clean(inline);
  for (let i = idx - 1; i >= 0 && i >= idx - 3; i -= 1) {
    const prev = clean(lines[i]);
    if (prev.length >= 8 && !CHROME_RE.test(prev)) return prev;
  }
  return clean(inline);
}

/**
 * @param {{subject?: string, text?: string, html?: string}} email
 * @returns {Array<object>} raw job records; [] when nothing parseable is found.
 *                          Never throws - a malformed email must not stall the
 *                          workflow, it must fall through to the WF3 canary.
 */
function parseVollnaEmail(email) {
  const source = email && typeof email === 'object' ? email : {};
  const body = source.text && source.text.trim()
    ? String(source.text)
    : htmlToText(source.html);
  if (!body) return [];

  const hits = [];
  JOB_URL_RE.lastIndex = 0;
  let m;
  while ((m = JOB_URL_RE.exec(body)) !== null) {
    hits.push({ url: m[0], jobId: m[1], index: m.index });
    if (hits.length > 200) break; // pathological input guard
  }
  if (!hits.length) return [];

  // One segment per job: from the start of the line holding this job's URL to
  // the start of the line holding the next one.
  const lineStart = (i) => body.lastIndexOf('\n', i) + 1;
  const seen = new Set();
  const jobs = [];

  for (let i = 0; i < hits.length; i += 1) {
    const hit = hits[i];
    if (seen.has(hit.jobId)) continue; // Vollna repeats the link in "Apply now"
    seen.add(hit.jobId);
    const from = lineStart(hit.index);
    const nextNew = hits.slice(i + 1).find((h) => !seen.has(h.jobId));
    const to = nextNew ? lineStart(nextNew.index) : body.length;
    const segment = body.slice(from, to);

    const title = extractTitle(segment, hit.url);
    const hourly = match(segment, 'hourlyRange');
    const hourlyOne = hourly ? null : match(segment, 'hourlySingle');
    const fixed = match(segment, 'fixedBudget');
    const spend = match(segment, 'clientSpend');
    const rating = match(segment, 'clientRating');

    jobs.push({
      job_id: hit.jobId,
      url: hit.url,
      title,
      description: extractDescription(segment, title),
      budget_type: hourly || hourlyOne ? 'hourly' : fixed ? 'fixed' : 'unknown',
      budget_fixed: fixed ? toNumber(fixed[1]) : null,
      budget_hourly_min: hourly ? toNumber(hourly[1]) : hourlyOne ? toNumber(hourlyOne[1]) : null,
      budget_hourly_max: hourly ? toNumber(hourly[2]) : hourlyOne ? toNumber(hourlyOne[1]) : null,
      client_total_spent: spend ? toNumber(spend[1], spend[2]) : null,
      client_hires: match(segment, 'clientHires') ? Number(match(segment, 'clientHires')[1]) : null,
      client_jobs_posted: match(segment, 'clientJobsPosted')
        ? Number(match(segment, 'clientJobsPosted')[1]) : null,
      client_rating: rating ? Number(rating[1]) : null,
      client_payment_verified: Boolean(match(segment, 'paymentVerified')),
      client_country: match(segment, 'country') ? match(segment, 'country')[1].trim() : null,
      proposals: match(segment, 'proposals') ? Number(match(segment, 'proposals')[1]) : null,
      experience_level: match(segment, 'experienceLevel')
        ? match(segment, 'experienceLevel')[1].toLowerCase() : null,
      posted_at_raw: match(segment, 'postedAt') ? match(segment, 'postedAt')[1].trim() : null,
      alert_subject: source.subject ? String(source.subject) : null,
      raw_segment: segment,
    });
  }

  return jobs;
}
// ==END INLINED src/parse-vollna.js==

// ==BEGIN INLINED src/normalize.js==
/**
 * Turn a raw parsed job into the canonical record every downstream step uses:
 * the Data Table row, the scoring prompt, the Slack card, the draft prompt.
 *
 * Pure and idempotent. Inlined into the n8n "parse" Code node alongside
 * parse-vollna.js, so it must stay dependency free.
 */

const SCHEMA_VERSION = 1;

/** Collapse whitespace and clip, so a runaway description can't blow up a prompt. */
function clean(s, max = 4000) {
  if (s == null) return '';
  const out = String(s).replace(/\s+/g, ' ').trim();
  return out.length > max ? `${out.slice(0, max - 1)}…` : out;
}

function money(n) {
  if (n == null || !Number.isFinite(n)) return null;
  return Math.round(n);
}

/** Human-readable budget for the Slack card and the prompt. */
function budgetDisplay(job) {
  if (job.budget_type === 'hourly') {
    const lo = job.budget_hourly_min;
    const hi = job.budget_hourly_max;
    if (lo && hi && lo !== hi) return `$${lo}-$${hi}/hr`;
    if (lo) return `$${lo}/hr`;
    return 'hourly, rate not stated';
  }
  if (job.budget_type === 'fixed') {
    return job.budget_fixed ? `$${money(job.budget_fixed)} fixed` : 'fixed, budget not stated';
  }
  return 'not stated';
}

/**
 * Client credibility summary in the form the rubric reasons about. Posted
 * budget is a weak signal and placeholder budgets are common, so the prompt is
 * handed spend/hires/rating explicitly rather than left to infer them.
 */
function clientSummary(job) {
  const parts = [];
  parts.push(job.client_payment_verified ? 'payment verified' : 'payment NOT verified');
  if (job.client_total_spent != null) parts.push(`$${money(job.client_total_spent)} total spent`);
  else parts.push('spend unknown');
  if (job.client_hires != null) parts.push(`${job.client_hires} hires`);
  if (job.client_jobs_posted != null) parts.push(`${job.client_jobs_posted} jobs posted`);
  if (job.client_rating != null) parts.push(`${job.client_rating}/5 rating`);
  if (job.client_country) parts.push(job.client_country);
  return parts.join(', ');
}

/**
 * @param {object} raw a record from parseVollnaEmail(), or an already
 *                     normalized record (in which case it is returned as-is
 *                     apart from re-derived display fields).
 */
function normalizeJob(raw) {
  const j = raw && typeof raw === 'object' ? raw : {};
  const normalized = {
    schema_version: SCHEMA_VERSION,
    job_id: clean(j.job_id, 64),
    url: clean(j.url, 500),
    title: clean(j.title, 250),
    description: clean(j.description, 4000),
    budget_type: ['hourly', 'fixed', 'unknown'].includes(j.budget_type) ? j.budget_type : 'unknown',
    budget_fixed: money(j.budget_fixed),
    budget_hourly_min: money(j.budget_hourly_min),
    budget_hourly_max: money(j.budget_hourly_max),
    client_total_spent: money(j.client_total_spent),
    client_hires: Number.isFinite(j.client_hires) ? j.client_hires : null,
    client_jobs_posted: Number.isFinite(j.client_jobs_posted) ? j.client_jobs_posted : null,
    client_rating: Number.isFinite(j.client_rating) ? j.client_rating : null,
    client_payment_verified: Boolean(j.client_payment_verified),
    client_country: j.client_country ? clean(j.client_country, 60) : null,
    proposals: Number.isFinite(j.proposals) ? j.proposals : null,
    experience_level: j.experience_level ? clean(j.experience_level, 30) : null,
    posted_at_raw: j.posted_at_raw ? clean(j.posted_at_raw, 60) : null,
    alert_subject: j.alert_subject ? clean(j.alert_subject, 200) : null,
  };
  normalized.budget_display = budgetDisplay(normalized);
  normalized.client_summary = clientSummary(normalized);
  return normalized;
}

/** A job is worth scoring only if we got the two fields the rubric needs. */
function isScorable(job) {
  return Boolean(job && job.job_id && job.title && job.title.length >= 8);
}
// ==END INLINED src/normalize.js==

// ==BEGIN INLINED src/state.js==
/**
 * Dedupe and status state for the pipeline.
 *
 * Deliberately a set of pure functions over a plain object, so the whole
 * lifecycle is unit testable. In n8n the object is the workflow's static data
 * (`$getWorkflowStaticData('global')`), which n8n persists in its own database
 * and which therefore survives container restarts and Docker image upgrades.
 *
 * Why not a Data Table or SQLite node: this needs to behave identically on the
 * n8n Cloud trial and on the micro PC, with no node parameters to get wrong and
 * no writable volume to depend on. The trade-off is that state is not
 * queryable from outside n8n and should stay small - hence prune(). When the
 * proposal log needs to be a real queryable store (Phase 2 tuning against reply
 * data), move it to SQLite on the micro PC volume and keep this module for
 * dedupe only.
 */

const STATUS = {
  SEEN: 'seen',
  REJECTED: 'rejected',
  QUALIFIED: 'qualified',
  DRAFTED: 'drafted',
  SKIPPED: 'skipped',
  ERROR: 'error',
};

/** Get the jobs map, creating it on first use. Mutates `state` by design. */
function jobsOf(state) {
  if (!state || typeof state !== 'object') throw new Error('state must be an object');
  if (!state.jobs || typeof state.jobs !== 'object') state.jobs = {};
  return state.jobs;
}

function hasSeen(state, jobId) {
  return Object.prototype.hasOwnProperty.call(jobsOf(state), String(jobId));
}

/**
 * Record a first sighting. Returns false and touches nothing if the job is
 * already known, which is exactly the dedupe decision the workflow branches on.
 */
function markSeen(state, job, now = Date.now()) {
  const jobs = jobsOf(state);
  const id = String(job.job_id);
  if (!id) throw new Error('cannot mark a job with no job_id');
  if (Object.prototype.hasOwnProperty.call(jobs, id)) return false;
  jobs[id] = {
    status: STATUS.SEEN,
    title: job.title || '',
    url: job.url || '',
    first_seen: now,
    updated: now,
  };
  return true;
}

function updateStatus(state, jobId, status, extra = {}, now = Date.now()) {
  const jobs = jobsOf(state);
  const id = String(jobId);
  if (!Object.prototype.hasOwnProperty.call(jobs, id)) {
    throw new Error(`cannot update unknown job ${id}`);
  }
  if (!Object.values(STATUS).includes(status)) throw new Error(`unknown status ${status}`);
  jobs[id] = { ...jobs[id], ...extra, status, updated: now };
  return jobs[id];
}

function get(state, jobId) {
  return jobsOf(state)[String(jobId)] || null;
}

/** How many jobs were first seen in the window. This is the WF3 canary input. */
function countSince(state, sinceMs) {
  return Object.values(jobsOf(state)).filter((j) => j.first_seen >= sinceMs).length;
}

function countByStatus(state) {
  const out = {};
  for (const j of Object.values(jobsOf(state))) out[j.status] = (out[j.status] || 0) + 1;
  return out;
}

/**
 * Drop records older than maxAgeDays so static data cannot grow without bound.
 * Drafted jobs are kept regardless - they are the record of what was actually
 * sent, and Phase 2 retunes the rubric against them.
 */
function prune(state, maxAgeDays = 120, now = Date.now()) {
  const jobs = jobsOf(state);
  const cutoff = now - maxAgeDays * 24 * 60 * 60 * 1000;
  let removed = 0;
  for (const [id, j] of Object.entries(jobs)) {
    if (j.status === STATUS.DRAFTED) continue;
    if (j.first_seen < cutoff) {
      delete jobs[id];
      removed += 1;
    }
  }
  return removed;
}
// ==END INLINED src/state.js==

// ---- node logic ----
const state = $getWorkflowStaticData('global');
prune(state, 120);

const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  const email = {
    subject: d.subject || d.Subject || (d.headers && d.headers.subject) || null,
    text: d.textPlain || d.text || d.textAsHtml || null,
    html: d.textHtml || d.html || null,
  };

  for (const raw of parseVollnaEmail(email)) {
    const job = normalizeJob(raw);
    if (!isScorable(job)) continue;          // no usable title: nothing to score
    if (!markSeen(state, job)) continue;     // dedupe: already known
    out.push({ json: job });
  }
}

// No new jobs is a normal outcome, not an error. Returning [] ends the branch.
return out;

// GENERATED by scripts/build-workflow.mjs - do not edit in the n8n UI.
// Edit the module under src/ (or context/), run ./test.sh, re-import.

// ==BEGIN INLINED src/thresholds.js==
/**
 * Every tunable number in the pipeline. One file so Phase 2 retuning is a
 * single reviewable diff, and so the eval harness and the workflow can never
 * disagree about the threshold.
 */

/** Scores at or above this get a Slack card. Below, the job is logged and dropped. */
const SCORE_THRESHOLD = 70;

/** Slack Send-and-Wait timeout. A Friday-night post must survive the weekend. */
const APPROVAL_TIMEOUT_HOURS = 72;

/** WF3 fires if fewer than this many jobs were seen in the last 24h. */
const MIN_JOBS_PER_DAY = 1;

/** Draft length gate, enforced by the draft eval and stated in the prompt. */
const DRAFT_MIN_WORDS = 120;
const DRAFT_MAX_WORDS = 350;

/** Model choices. Scoring is high-volume and mechanical; drafting is not. */
const SCORING_MODEL = 'claude-haiku-4-5';
const DRAFTING_MODEL = 'claude-sonnet-5';

/** Drafting effort. Sonnet 5 accepts low|medium|high|xhigh|max. */
const DRAFT_EFFORT = 'low';

/**
 * Scoring response mode. 'structured' uses output_config.format; 'tool' uses a
 * strict tool with forced tool_choice. Settle this with scripts/check-json-mode.mjs
 * before wiring the workflow - it is a live-API fact, not a guess.
 */
const SCORING_JSON_MODE = 'structured';
// ==END INLINED src/thresholds.js==

// ==BEGIN INLINED src/score-prompt.js==
/**
 * Build the Anthropic /v1/messages request that scores one job.
 *
 * Pure: takes a normalized job plus the context pack, returns a request body.
 * The same builder feeds the n8n Code node and scripts/run-eval.mjs, which is
 * the whole point - the eval scores the exact prompt production sends.
 */

const SCORE_SCHEMA = {
  type: 'object',
  properties: {
    score: {
      type: 'integer',
      minimum: 0,
      maximum: 100,
      description: 'Overall fit and client-quality score.',
    },
    verdict: {
      type: 'string',
      enum: ['qualify', 'maybe', 'reject'],
    },
    reasoning: {
      type: 'string',
      description: 'One or two sentences. What decided this score. No preamble.',
    },
    red_flags: {
      type: 'array',
      items: { type: 'string' },
      description: 'Short phrases naming concrete red flags found. Empty array if none.',
    },
  },
  required: ['score', 'verdict', 'reasoning', 'red_flags'],
  additionalProperties: false,
};

function jobBlock(job) {
  return [
    `Title: ${job.title}`,
    `Budget: ${job.budget_display}`,
    `Experience level requested: ${job.experience_level || 'not stated'}`,
    `Proposals so far: ${job.proposals == null ? 'not stated' : job.proposals}`,
    `Posted: ${job.posted_at_raw || 'not stated'}`,
    `Client: ${job.client_summary}`,
    '',
    'Description:',
    job.description || '(no description captured from the alert email)',
  ].join('\n');
}

/**
 * @param {object} job normalized job (see src/normalize.js)
 * @param {{rubric: string}} ctx context pack
 * @param {{model?: string, mode?: 'structured'|'tool'}} [opts]
 */
function buildScoreRequest(job, ctx, opts = {}) {
  const model = opts.model || 'claude-haiku-4-5';
  const mode = opts.mode || 'structured';

  const system = [
    'You screen Upwork job postings for a senior automation consultant.',
    'Apply the rubric below exactly. Return only the structured result.',
    '',
    ctx.rubric,
  ].join('\n');

  const base = {
    model,
    max_tokens: 1024,
    system,
    messages: [{ role: 'user', content: jobBlock(job) }],
  };

  // No cache_control here on purpose: the rubric prefix is well under the
  // minimum cacheable prefix for a Haiku-class model, so a breakpoint would
  // cost a write and never read. The drafting call is where caching pays.

  if (mode === 'tool') {
    return {
      ...base,
      tools: [{
        name: 'record_score',
        description: 'Record the screening result for this job.',
        input_schema: SCORE_SCHEMA,
        strict: true,
      }],
      tool_choice: { type: 'tool', name: 'record_score' },
    };
  }

  return {
    ...base,
    output_config: {
      format: { type: 'json_schema', schema: SCORE_SCHEMA },
    },
  };
}

/**
 * Pull the score object out of an API response, whichever mode produced it.
 * Throws on an unusable response so the n8n node fails loudly and the error
 * workflow fires - a silently defaulted score would let bad jobs through.
 */
function parseScoreResponse(response) {
  if (!response || typeof response !== 'object') throw new Error('empty scoring response');
  if (response.stop_reason === 'refusal') {
    throw new Error(`scoring refused: ${response.stop_details?.category || 'unknown'}`);
  }
  const blocks = Array.isArray(response.content) ? response.content : [];

  const toolBlock = blocks.find((b) => b.type === 'tool_use' && b.name === 'record_score');
  if (toolBlock) return validateScore(toolBlock.input);

  const textBlock = blocks.find((b) => b.type === 'text' && b.text && b.text.trim());
  if (!textBlock) throw new Error('scoring response contained no text or tool_use block');
  // Tolerate a fenced block, which is what a non-structured fallback produces.
  const raw = textBlock.text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '');
  return validateScore(JSON.parse(raw));
}

function validateScore(obj) {
  const o = obj && typeof obj === 'object' ? obj : {};
  const score = Number(o.score);
  if (!Number.isFinite(score) || score < 0 || score > 100) {
    throw new Error(`score out of range: ${JSON.stringify(o.score)}`);
  }
  if (!['qualify', 'maybe', 'reject'].includes(o.verdict)) {
    throw new Error(`unknown verdict: ${JSON.stringify(o.verdict)}`);
  }
  return {
    score: Math.round(score),
    verdict: o.verdict,
    reasoning: String(o.reasoning || '').trim(),
    red_flags: Array.isArray(o.red_flags) ? o.red_flags.map(String) : [],
  };
}
